-- El juego de caracteres se fija SIEMPRE: el cliente mysql lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;

-- ================================================================================================
-- Salinas y Arenales de San Pedro del Pinatar · Fase 3 (N3): puntos de interés.
--
-- GENERADO por Tools/catalogo-nacional/build-poi-sql.js desde el bloque `pointsOfInterest` de
-- Frontend/Data/parks/murcia/salinas-arenales-san-pedro-pinatar/park.json. No editar a mano: regenerar con
--   node Tools/catalogo-nacional/build-poi-sql.js --park salinas-arenales-san-pedro-pinatar
--
-- Hace falta porque Frontend/Js/data.js da PRIORIDAD a la API sobre el park.json empaquetado: en un
-- despliegue con backend, sin este SQL el espacio se seguiría sirviendo con 0 puntos de interés.
--
-- ANTES DE APLICAR, comprobar que el espacio tiene fila en `parks`. Si no la tiene, el
-- INSERT ... SELECT de abajo no encuentra nada y **carga cero filas sin dar ningún error** (le pasó
-- a Sierra Espuña el 2026-08-08):
--   SELECT id, slug, name FROM parks WHERE slug = 'salinas-arenales-san-pedro-pinatar';
--
-- Idempotente: ON DUPLICATE KEY UPDATE sobre la clave única (park_id, slug). Aplicar con:
--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database/n3-pois-salinas-arenales-san-pedro-pinatar.sql
-- ================================================================================================

-- 16 punto(s) de interés.
INSERT INTO points_of_interest (park_id, slug, name, type, description, latitude, longitude, image_url, source, is_approx, orden)
SELECT p.id, poi.slug, poi.name, poi.type, poi.description, poi.latitude, poi.longitude, poi.image_url, poi.source, poi.is_approx, poi.orden
FROM parks p
JOIN (
    SELECT 'molino-de-quintin' slug, 'Molino de Quintín' name, 'Cultural' type, 'Molino de viento salinero de dos tímpanos, construido en el primer tercio del siglo XX para trasvasar agua desde los canales que vienen del Mar Menor hacia las balsas calentadoras de las salinas. Dejó de funcionar a principios de los años setenta, cuando unas bombas eléctricas lo sustituyeron. No es un molino harinero: no molía nada, elevaba agua, y por eso su maquinaria y su emplazamiento al borde de la mota son distintos de los de un molino de cereal. Tiene incoado expediente de declaración como Bien de Interés Cultural.' description, 37.820414 latitude, -0.775995 longitude, 'https://commons.wikimedia.org/wiki/Special:FilePath/Molino_de_Quint%C3%ADn%2C_Salinas_de_San_Pedro_del_Pinatar_(6065429806).jpg?width=1280' image_url, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §2.3.4 «Patrimonio cultural» (expediente de BIC incoado, tipología de molino salinero de dos tímpanos) y §7.3.4 Tabla 20, unidad 8 «La Mota»; catálogo «Monumentos en la Región de Murcia» de la CARM, ficha 364 «Molinos de Quintín y Calcetera» (Paseo de la Mota), consultado el 2026-08-17 vía datos.gob.es → nexo.carm.es, que aporta la fecha de construcción y el fin del uso. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL), que es quien separa los dos molinos: la ficha de la CARM da UNA sola coordenada para los dos y están a 2,4 km. La traza del PR-MU 65 pasa a 32 m, pero lo que se señala es el molino, no el sendero; Wikimedia Commons (foto: amaianos from Galicia, CC BY 2.0)' source, FALSE is_approx, 0 orden
    UNION ALL
    SELECT 'molino-de-la-calcetera', 'Molino de la Calcetera', 'Cultural', 'El segundo de los dos molinos salineros del parque, gemelo del de Quintín en tipología y función: elevar el agua del Mar Menor hacia las balsas donde se concentra la sal. Marca el extremo suroeste de la mota que separa las salinas de la laguna, y como su pareja tiene incoado expediente de Bien de Interés Cultural y está en desuso desde los años setenta.', 37.799074, -0.761074, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §2.3.4 «Patrimonio cultural» y §7.3.4 Tabla 20, unidad 8 «La Mota», que lo sitúa en el extremo suroeste de las salinas; catálogo «Monumentos en la Región de Murcia» de la CARM, ficha 364. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL). La traza del PR-MU 65 pasa a 24 m, pero lo que se señala es el molino, no el sendero', FALSE, 1
    UNION ALL
    SELECT 'banos-de-lodo', 'Baños de lodo', 'Natural', 'Charca somera de la orilla del Mar Menor cuyos fangos negros, ricos en sales y materia orgánica, se usan desde hace generaciones para embadurnarse y secarse al sol antes de enjuagarse en la laguna. El plan de gestión lo recoge como un uso etnológico del espacio, no como una instalación: no hay más equipamiento que la propia orilla. Está en la unidad de La Mota, junto al camino que une los dos molinos.', 37.818122, -0.774038, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C3%B1os_de_lodo_en_San_Pedro_del_Pinatar.jpg?width=1280', 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.4 Tabla 20, unidad 8 «La Mota», que enumera entre sus contenidos «Etnológico: área de baños terapéuticos de lodo», y §7.3.2 Tabla 17, que sitúa un observatorio de aves en la «charca grande de baños de lodo junto a Molino de Quintín». coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: Anidae, CC BY-SA 4.0)', FALSE, 2
    UNION ALL
    SELECT 'gola-de-la-torre', 'Gola de la Torre', 'Natural', 'Uno de los dos canales naturales por los que el Mar Menor se comunica con el Mediterráneo, y sobre el que se monta la encañizada de La Torre: un arte de pesca tradicional hecho de cañas clavadas en el fondo que encauza el pescado hacia unas cámaras a medida que entra o sale con las corrientes. El nivel del agua sube y baja aquí lo bastante como para crear una zona pseudomareal, algo poco frecuente en el Mediterráneo, y esa oscilación es justo lo que hace funcionar la encañizada.', 37.784633, -0.759841, 'https://commons.wikimedia.org/wiki/Special:FilePath/ENCA%C3%91IZADA001.jpg?width=1280', 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §2.1.4 «Relieve y geomorfología» (Las Encañizadas como «único punto del Mar Menor que de forma natural se abre a la entrada del Mediterráneo» y como zona pseudomareal), §2.3.4 «Patrimonio cultural», que cita el sistema de encañizadas de La Torre y El Ventorrillo entre los elementos de interés cultural recogidos por el PORN, y §7.3.4 Tabla 20, unidad 9. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: Nioger, CC BY 2.5) — la foto retrata el sistema de encañizadas, del que esta gola es una de las dos, y no lleva geoetiqueta: no se puede afirmar que sea ésta y no la del Ventorrillo', FALSE, 3
    UNION ALL
    SELECT 'gola-del-ventorrillo', 'Gola del Ventorrillo', 'Natural', 'La segunda gola de Las Encañizadas, y la segunda de las dos encañizadas que el plan de ordenación reconoce como patrimonio del espacio. Alrededor de estos canales se levantan las edificaciones de madera que daban apoyo a los pescadores, y los escollos de calcoarenita que asoman frente a la costa han ido formando islas triangulares al abrigo del oleaje: una acumulación de arena a cada lado del escollo que acaba uniéndose por detrás.', 37.788748, -0.760837, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §2.3.4 «Patrimonio cultural» (sistema de encañizadas de La Torre y El Ventorrillo, y edificaciones asociadas), §2.1.4, que describe la formación tombólica triple entre escollos enfrentados, y §7.3.4 Tabla 20, unidad 9 «Las Encañizadas». coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL)', FALSE, 4
    UNION ALL
    SELECT 'punta-de-algas', 'Punta de Algas', 'Geológico', 'Afloramiento de las calcoarenitas miocénicas que sirven de base a todo el sistema salinero, y punto desde el que arranca hacia el sur una restinga de piedras sumergidas y bajos de arena que los pescadores llaman los Punchosos. Es uno de los pocos resaltes de un parque que, por lo demás, es llano: aquí la costa deja de ser arena y pasa a ser roca baja.', 37.791064, -0.748695, 'https://commons.wikimedia.org/wiki/Special:FilePath/Playa_de_Punta_de_Algas_-_Salinas_y_Arenales_de_San_Pedro_del_Pinatar%2C_Spain_2024-02-06_(01).jpg?width=1280', 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §2.1.4 «Relieve y geomorfología» («como afloramiento del sustrato miocénico, desde Punta de Algas, se extiende paralelamente a la costa una restinga de piedras ahogadas y bajos de arenas conocidos como Punchosos») y §7.3.3 Tabla 18, que la enumera entre los enclaves de costa baja rocosa. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: Ryan Hodnett, CC BY-SA 4.0)', FALSE, 5
    UNION ALL
    SELECT 'escull-de-las-cruces', 'Escull de las Cruces', 'Geológico', 'Escollo de calcoarenita frente a la costa de Las Encañizadas, el más septentrional de los tres que se pueden situar. Los bloques fracturados que forman estos escollos se alargan en paralelo a la línea de costa, porque es el oleaje el que los ha ido recortando así, y al abrigo de cada uno se acumula arena por los dos lados.', 37.788606, -0.747995, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.3 Tabla 18, que enumera los enclaves de costa baja rocosa del parque —Escull de la Caleta, Escull del Algodón, Escull de los Valientes, Escull de las Cruces y Punta de Algas— como el único relieve destacable de un espacio llano, y §2.1.4, que describe cómo se forman. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL)', FALSE, 6
    UNION ALL
    SELECT 'escull-de-los-valientes', 'Escull de los Valientes', 'Geológico', 'El escollo central de los tres de Las Encañizadas. Entre el cordón de arena central, ya relicto, y los laterales que siguen funcionando quedan charcas someras, y ese mosaico de agua quieta y arena es lo que usan como comedero las aves limícolas que paran aquí.', 37.787368, -0.747679, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.3 Tabla 18 (enclaves de costa baja rocosa) y §2.1.4, que describe la formación tombólica triple y las charcas que quedan entre cordones. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL)', FALSE, 7
    UNION ALL
    SELECT 'escull-del-algodon', 'Escull del Algodón', 'Geológico', 'El más meridional de los escollos que se pueden situar, ya en el tramo donde las playas se cubren de arribazones: montones de restos de posidonia que el mar deja en la orilla y que, lejos de ser suciedad, sujetan la arena en los temporales y alimentan una comunidad de plantas anuales propia.', 37.786257, -0.746874, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.3 Tabla 18 (enclaves de costa baja rocosa) y §2.1.4, que describe las playas limosas y de restos de Posidonia oceanica que bordean Las Encañizadas. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL)', FALSE, 8
    UNION ALL
    SELECT 'playa-de-la-torre-derribada', 'Playa de la Torre Derribada', 'Natural', 'Playa de arena fina respaldada por el cordón dunar, con las dunas embrionarias en contacto directo con la orilla y, tras ellas, las dunas primarias, que aquí llegan a los cuatro metros de altura. Le da nombre una torre vigía de la que quedan restos. Es una de las unidades del parque en las que el plan de gestión admite uso turístico además del didáctico y el científico.', 37.82375, -0.757787, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torrederribada.jpg?width=1280', 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.4 Tabla 20, unidad 4 «Playa de la Torre Derribada», que le reconoce contenido geomorfológico (playa), florístico (vegetación psammófila), faunístico (aves limícolas y marinas) e histórico (torre vigía), y §2.1.4, que da la altura de las dunas primarias al norte del puerto. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: No machine-readable author provided. Nioger assumed (based on copyr…, CC BY 2.5) — la foto no lleva geoetiqueta; la sitúa su categoría de Commons, «Playa de la Torre Derribada», que es la de esta playa concreta', FALSE, 9
    UNION ALL
    SELECT 'playa-de-la-llana', 'Playa de La Llana', 'Natural', 'La playa más larga del parque, y la que mejor enseña el perfil completo del sistema: la orilla, las dunas móviles con el barrón sujetándolas, y por detrás los arenales con el sabinar y el saladar. El plan la separa en dos unidades —la playa y los arenales— porque toleran usos distintos: la primera admite visita turística y la segunda es zona de conservación prioritaria.', 37.798489, -0.752712, 'https://commons.wikimedia.org/wiki/Special:FilePath/Playa_de_La_Llana_-_Salinas_y_Arenales_de_San_Pedro_del_Pinatar%2C_Spain_2024-02-06.jpg?width=1280', 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.4 Tabla 20, unidades 6 «Playas de La Llana» (uso didáctico, científico, divulgativo y turístico) y 7 «Arenales de La Llana» (Zona de Conservación Prioritaria), y §2.1.4 para el perfil de playa y duna. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL); Wikimedia Commons (foto: Ryan Hodnett, CC BY-SA 4.0)', FALSE, 10
    UNION ALL
    SELECT 'pinar-del-coterillo', 'Pinar del Coterillo', 'Paisajístico', 'Pinar de repoblación plantado a principios del siglo XX para fijar las dunas y frenar su avance sobre los estanques salineros. No es un bosque espontáneo: es una obra de ingeniería forestal que lleva un siglo funcionando, y bajo sus pinos se ha ido instalando el sabinar y la vegetación de arena. El plan lo clasifica como zona de conservación prioritaria y le da la fragilidad máxima.', 37.833115, -0.762513, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.4 Tabla 20, unidad 3 «Pinar del Coterillo», que registra como contenido etnológico el «pinar de repoblación efectuada a principios del siglo XX, para fijación de dunas» y le asigna fragilidad 5 sobre 5. La coordenada es el centro del polígono de bosque que OpenStreetMap rotula «Cotorrillo de las Salinas», con grafía distinta a la del plan: es una masa de pinar en la posición que el plan describe, pero la correspondencia no está confirmada por ninguna fuente, de ahí approx. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL)', TRUE, 11
    UNION ALL
    SELECT 'observatorio-de-aves', 'Observatorio de aves', 'Paisajístico', 'Caseta de observación desde la que mirar las charcas sin que las aves te vean: una pared con troneras a la altura de los ojos, orientada al agua. Es lo que hace posible ver de cerca a flamencos, cigüeñuelas y avocetas sin levantarlas del comedero, que es justo lo que las ahuyenta de un salinar.', 37.837156, -0.765919, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.2 Tabla 17, que enumera cuatro observatorios de aves entre los equipamientos interpretativos del parque —dos en la charca de El Coterillo, uno junto a la torre del pinar y otro en la charca grande de los baños de lodo—; la tabla no da coordenadas y no se afirma cuál de los cuatro es éste. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL), que rotula un mirador con este nombre dentro del límite. El faro de San Pedro del Pinatar está a 16 m, por debajo del umbral del §4.3.7: es el mismo punto del mapa con dos elementos distintos, y se señala el observatorio porque es el que tiene fuente documental detrás', FALSE, 12
    UNION ALL
    SELECT 'puerto-de-san-pedro', 'Puerto de San Pedro', 'Acceso', 'Puerto pesquero y deportivo encajado en mitad del parque, y la puerta de entrada por la que llega la mayoría de los visitantes. Tiene además un efecto que se ve en el mapa: la deriva litoral lleva la arena de norte a sur, y el dique la intercepta, de modo que al norte del puerto la playa es ancha y al sur está en retroceso.', 37.821792, -0.75781, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.4 Tabla 20, unidad 5 «Puerto de San Pedro» (Zona de Uso Intensivo General; uso pesquero, acuicultura y turístico-deportivo, accesibilidad 5 sobre 5), y §2.1.4, que atribuye al puerto el corte del transporte de sedimentos y la erosión de la costa al sur. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL)', FALSE, 13
    UNION ALL
    SELECT 'centro-de-visitantes-las-salinas', 'Centro de Visitantes «Las Salinas»', 'Acceso', 'El equipamiento de recepción del parque, alojado en el Centro de Investigación y Conservación de Humedales «Las Salinas», que hace a la vez de centro de visitantes y de centro científico. Tiene sala de interpretación y una torre-mirador sobre los estanques, y es donde se concentran las actividades de educación ambiental desde que en 2011 se trasladaron aquí las que se hacían en el aula de naturaleza del Molino de Quintín.', 37.834953, -0.778428, NULL, 'PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar», volumen III del Plan de gestión integral del Mar Menor (Decreto n.º 259/2019, BORM n.º 242 de 19.10.2019), §7.3.2 Tabla 17, que lo lista entre los equipamientos de titularidad regional del parque (información y atención al visitante, sala de interpretación, mirador paisajístico, área recreativa, aparcamiento y aseos). ENTRA POR DECISIÓN EXPLÍCITA a 72 m FUERA del límite oficial, por encima del margen de ~50 m del §4.3.3: el propio plan advierte en su §7.3.4 que la unidad de uso público «Las Palomas», donde está, queda fuera del Parque Regional y se evalúa igualmente por alojar sus equipamientos y estar «fuertemente ligada a la gestión del Parque». Mismo criterio que el yacimiento de Cañada Molina en Sierra de la Pila, admitido a 69 m. coordenada de OpenStreetMap (© OpenStreetMap contributors, ODbL)', FALSE, 14
    UNION ALL
    SELECT 'yacimiento-romano-la-raya', 'Yacimiento romano de La Raya', 'Arqueológico', 'Villa romana excavada en campañas sucesivas desde 2002, de la que se ha delimitado el perímetro y sacado a la luz estructuras de muros, cerámica y estucos pintados. Lo que se ve corresponde probablemente a un borde exterior: el conjunto pudo alcanzar los 10.000 m² entre dependencias señoriales, de servicio, zonas de trabajo y cuadras. Se interpreta como villa de recreo y a la vez comercial, por su cercanía al fondeadero del Mediterráneo.', 37.8260702, -0.7759098, NULL, 'Catálogo «Monumentos en la Región de Murcia» de la CARM (Instituto de Turismo), ficha 5147 «Yacimiento Romano La Raya», consultado el 2026-08-17 vía datos.gob.es → nexo.carm.es; de ahí salen el hecho, la descripción y la coordenada. CAE A 39 m FUERA del límite oficial, dentro del margen de ~50 m del §4.3.3, y los metros constan aquí. OJO con la coordenada de esa fuente: sus campos «Latitud» y «Longitud» vienen intercambiados en esta ficha, y en otras traen UTM 30N; la de aquí se ha comprobado con point-in-polygon contra el límite del parque. No se identifica con la «villa romana de recreo de El Salar» que cita el §2.3.4 del PRUG: son dos topónimos distintos y ninguna fuente los equipara', FALSE, 15
) poi
WHERE p.slug = 'salinas-arenales-san-pedro-pinatar'
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    type = VALUES(type),
    description = VALUES(description),
    latitude = VALUES(latitude),
    longitude = VALUES(longitude),
    image_url = VALUES(image_url),
    source = VALUES(source),
    is_approx = VALUES(is_approx),
    orden = VALUES(orden);

-- Comprobación posterior: debe devolver 16.
SELECT COUNT(*) AS pois_cargados FROM points_of_interest poi
JOIN parks p ON p.id = poi.park_id WHERE p.slug = 'salinas-arenales-san-pedro-pinatar';
